// Basic HMAC SHA256 verification using a secret stored in environment or n8n credentials
const crypto = require('crypto');
const body = items[0].json;
const secret = $jsonParameters && $jsonParameters.secret || process.env.GITHUB_WEBHOOK_SECRET || '';
const signature = this.getNodeParameter('headers', '')['x-hub-signature-256'] || '';
if(!secret){
  throw new Error('No webhook secret configured.');
}
const payload = JSON.stringify(body);
const hmac = 'sha256=' + crypto.createHmac('sha256', secret).update(payload).digest('hex');
if(signature !== hmac){
  throw new Error('Invalid signature');
}
return items;
